import{_ as t,o as s,c as n,a5 as i}from"./chunks/framework.bIR-4glx.js";const g=JSON.parse('{"title":"使用 AI 学习一切：从真实问题到可验证交付","description":"以韩先凯的产品失败、恢复与重新进入 AI 实践为背景，建立面向普通学习者的问题、基线、练习、交付、验证和复盘闭环。","frontmatter":{"title":"使用 AI 学习一切：从真实问题到可验证交付","description":"以韩先凯的产品失败、恢复与重新进入 AI 实践为背景，建立面向普通学习者的问题、基线、练习、交付、验证和复盘闭环。","updated":"2026-10-15T00:00:00.000Z","sources_checked":"2026-10-15T00:00:00.000Z","source_review_interval":60},"headers":[],"relativePath":"threads/part-3/1-ai-learning.md","filePath":"threads/part-3/1-ai-learning.md","lastUpdated":1792022400000}'),e={name:"threads/part-3/1-ai-learning.md"};function l(r,a,d,p,h,o){return s(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="使用-ai-学习一切-从真实问题到可验证交付" tabindex="-1">使用 AI 学习一切：从真实问题到可验证交付 <a class="header-anchor" href="#使用-ai-学习一切-从真实问题到可验证交付" aria-label="Permalink to &quot;使用 AI 学习一切：从真实问题到可验证交付&quot;">​</a></h1><p>我叫韩先凯，也叫离谱。很多人先通过英语学习认识我，后来读到我做软件、开餐饮、经历公司失败、身体失序，又重新回到技术和 AI 的故事。今天我更愿意把 AI 当成一套学习基础设施，而不是一个替我思考的按钮。</p><p>这套方法来自一个不太体面的事实：回答可以很完整，产品却可能没有用户；代码可以运行，数据和安全却可能没有地基；一个人可以在聊天里显得很聪明，关闭对话后却不能独立完成任务。真正的学习结果必须在 AI 退出之后仍然存在：你能解释、判断、完成、迁移，并留下别人可以检查的证据。</p><p>需要把一次 AI 协作变成重复任务时，继续读<a href="./../practice/ai-workflows">AI 工作流实操</a>；准备比较版本或对外交付时，用<a href="./../../templates/ai-evaluation">AI 评测记录</a>保留失败、人工修改与成本。</p><p>面对不断出现的新工具，可以先读 <a href="./6-ai-trends-and-learning-roadmap">AI 趋势与学习路线</a>：区分已经观察到的能力、供应商的陈述和自己的预测，再选一个值得验证的变化。你不需要追上每次发布，需要的是逐渐形成自己的选择标准。</p><h2 id="本章速览" tabindex="-1">本章速览 <a class="header-anchor" href="#本章速览" aria-label="Permalink to &quot;本章速览&quot;">​</a></h2><ul><li>先定义真实结果，再决定 AI 介入哪一步；</li><li>用无 AI 基线、辅助版本和延迟独立复测区分学习与代做；</li><li>把来源、权限、隐私、成本和责任写进任务边界；</li><li>会话结束时保存状态，让下一次工作不依赖聊天记忆。</li></ul><h2 id="先看清这套方法从哪里来" tabindex="-1">先看清这套方法从哪里来 <a class="header-anchor" href="#先看清这套方法从哪里来" aria-label="Permalink to &quot;先看清这套方法从哪里来&quot;">​</a></h2><p>下面的内容是作者个人记录，不是研究结论，也不是给所有人的成功保证。每个案例都按四步阅读：发生了什么、当时哪里判断错了、形成什么原则、今天可以做什么练习。</p><p>如果你要分析一篇公开报道、一次 AI 项目经历或自己的失败记录，可以先复制<a href="./../../templates/ai-case-review">AI 经历案例复盘模板</a>，把来源、事实、判断、结果和可迁移原则分开。模板不能替你证明结果，但能防止叙事在不知不觉中变成结论。</p><h3 id="_2015–2016-从无处可去到真实用户" tabindex="-1">2015–2016：从无处可去到真实用户 <a class="header-anchor" href="#_2015–2016-从无处可去到真实用户" aria-label="Permalink to &quot;2015–2016：从无处可去到真实用户&quot;">​</a></h3><p>我曾因为实习和毕业手续受挫回到老家。2016 年开始折腾电影网站 <code>bt0.com</code>，后来接网站设计的单子。它不是什么宏大产品，却有真实用户、真实反馈和真实的使用痕迹。</p><p>当时最容易犯的错，是把“我能写出来”当成“别人需要它”。真正改变判断的不是又学了一门技术，而是有人使用、评价，甚至因为某个细节离开。</p><p><strong>原则</strong>：学习从真实问题开始，作品比收藏的答案更能暴露缺口。</p><p><strong>今天的练习</strong>：选一个身边人确实遇到的问题，先不用 AI 写一页解决方案，写下受众、动作、完成标准和你不知道的三件事。</p><h3 id="_2017–2022-从前端重构到组织与产品约束" tabindex="-1">2017–2022：从前端重构到组织与产品约束 <a class="header-anchor" href="#_2017–2022-从前端重构到组织与产品约束" aria-label="Permalink to &quot;2017–2022：从前端重构到组织与产品约束&quot;">​</a></h3><p>2017 年我进入一家为律师和律所服务的软件公司，从普通前端开发做到部门负责人、总经理和合伙人。早期产品来自外包，需求反复变化；后来我主导 Vue 重构，但产品发版后很长时间没有开单。</p><p>这段经历让我知道，努力、重构和功能数量都不能替代需求治理、用户验证和团队协作。一个人学会写代码，不代表组织已经学会交付。</p><p><strong>原则</strong>：学习目标要写成真实任务，而不是“了解某主题”；每一步都要有受众和验收标准。</p><p><strong>今天的练习</strong>：把“学习产品经理”改写成“在 45 分钟内为一个真实用户写出一页需求简报，并让对方指出一个不成立的假设”。</p><h3 id="_2022-把搜索和预设结果误认为-ai" tabindex="-1">2022：把搜索和预设结果误认为 AI <a class="header-anchor" href="#_2022-把搜索和预设结果误认为-ai" aria-label="Permalink to &quot;2022：把搜索和预设结果误认为 AI&quot;">​</a></h3><p>2022 年软件销量断崖式下降。高中同桌加入后，我们才看见项目结构老旧、性能和安全存在问题，所谓“大数据”和“AI”能力也没有真正的数据集和训练基础，部分功能本质上只是搜索与预设结果。</p><p>我们把很多精力放在 UI、多端适配和功能堆叠上，却没有先确认核心能力和数据是否真实存在。公司最终解散，亏损和歉疚都不能靠更漂亮的演示消失。</p><p><strong>原则</strong>：演示效果不等于能力，模型回答不等于事实，生成速度不等于交付质量。关键结论必须回到来源、测试、用户和责任人。</p><p><strong>今天的练习</strong>：让 AI 对一个熟悉主题生成解释；然后不用聊天记录，自己写出来源、反例、未知项和一个能推翻它的测试。不能写出的部分就是学习缺口。</p><h3 id="_2023-失败以后先恢复可行动性" tabindex="-1">2023：失败以后先恢复可行动性 <a class="header-anchor" href="#_2023-失败以后先恢复可行动性" aria-label="Permalink to &quot;2023：失败以后先恢复可行动性&quot;">​</a></h3><p>公司失败后，我关闭 GitHub，退出许多群，沉迷游戏，身体和生活都失去边界。回老家以后，真正的第一步不是再开一家公司，而是重新吃饭、睡觉、出门、面对过去，并把事情缩小到今天能完成的尺度。</p><p><strong>原则</strong>：学习系统必须考虑精力、健康和现实责任。连续执行比短期用力重要，低谷中也不应把“完成宏大逆转”当成验收标准。</p><p><strong>今天的练习</strong>：只安排 5–15 分钟，完成一项可保存的动作：整理一页笔记、运行一个测试、听一段材料或写三句话，然后记录实际完成情况，不用计划掩盖没有行动。</p><h3 id="_2026-重新进入-ai-与实体产业" tabindex="-1">2026：重新进入 AI 与实体产业 <a class="header-anchor" href="#_2026-重新进入-ai-与实体产业" aria-label="Permalink to &quot;2026：重新进入 AI 与实体产业&quot;">​</a></h3><p>2026 年我以中国词元云计算有限公司董事长的身份重新进入技术、企业服务和实体产业的实践，探索把 AI 接入农、林、牧、渔等真实场景，并计划为农村合作社提供免费的基础培训。这是实践方向和个人计划，不是已经证明的收入、客户数量或效果。</p><p><strong>原则</strong>：AI 最终要进入真实流程，接受成本、权限、隐私、用户反馈、故障和回滚的约束。</p><p><strong>今天的练习</strong>：选择一个真实组织的问题，写出数据从哪里来、谁能看、什么结果算通过、失败如何停止，以及你愿意承担的人工责任。</p><h2 id="七步闭环-先做事-再谈提示词" tabindex="-1">七步闭环：先做事，再谈提示词 <a class="header-anchor" href="#七步闭环-先做事-再谈提示词" aria-label="Permalink to &quot;七步闭环：先做事，再谈提示词&quot;">​</a></h2><ol><li><strong>定义真实结果</strong>：写清场景、受众、动作、截止时间和验收标准。</li><li><strong>保存无 AI 基线</strong>：先独立做一次，暴露知识缺口和判断盲点。</li><li><strong>准备可信材料</strong>：优先官方文档、教材、论文、数据、现有代码和真实案例。</li><li><strong>设计引导练习</strong>：让 AI 提问、解释、比较、提示和生成平行题，不代替关键步骤。</li><li><strong>主动产出</strong>：关闭材料后解释、编码、写作、计算、演示或做决定。</li><li><strong>通过多源反馈</strong>：AI 只是一个意见；来源、测试、专家、用户和安全审查共同判断。</li><li><strong>更新状态</strong>：保存作品、错误、成本、未决问题和下一项最小任务。</li></ol><p>缺少第 1 步，AI 会把愿望包装成答案；缺少第 2 步，你不知道能力是否增长；缺少第 6、7 步，错误会在下一次对话里重复。</p><h2 id="学习-ai-先弄懂五个层次" tabindex="-1">学习 AI，先弄懂五个层次 <a class="header-anchor" href="#学习-ai-先弄懂五个层次" aria-label="Permalink to &quot;学习 AI，先弄懂五个层次&quot;">​</a></h2><p>“使用 AI 学习”和“学习怎样构建 AI 应用”可以相互促进，却需要不同的练习。前者先保护自己的回忆、理解和表达；后者还要解释数据怎样进入系统、工具怎样执行、结果怎样被验证。可以用下面的层次定位问题，不必一开始就训练模型。</p><table tabindex="0"><thead><tr><th>层次</th><th>要能用自己的话解释</th><th>一项能留下证据的练习</th></tr></thead><tbody><tr><td>模型与输出</td><td>回答受输入与生成过程影响；流畅不等于真实</td><td>找出一个熟悉问题的错误答案，保存反证</td></tr><tr><td>上下文与检索</td><td>上下文是本次提供的材料；检索是找出相关材料再交给模型</td><td>用三页公开文档回答问题，每条结论标到原文位置</td></tr><tr><td>结构与工具</td><td>输出符合字段格式，不代表字段真实；提出工具调用，不代表动作已完成</td><td>检查缺字段、错误数字和工具失败三种情况</td></tr><tr><td>工作流与评测</td><td>步骤、权限、失败处理和验收共同决定系统是否可用</td><td>比较人工与 AI 流程，并保留失败和总耗时</td></tr><tr><td>学习与迁移</td><td>有工具时的成品质量，与自己的独立能力要分别衡量</td><td>三到七天后换一个条件，不看旧答案重做</td></tr></tbody></table><p>检索增强生成（RAG）通常在回答前引入检索到的材料；微调则通过训练改变模型参数。它们解决的问题不同。资料更新、缺少出处或检索范围错误，应先检查材料与检索；不能指望微调自动赋予最新事实、引用真实性或操作权限。先能说明失败在哪一层，再决定需要什么技术。</p><p>上述概念区别可参见 <a href="https://www.ibm.com/think/topics/rag-vs-fine-tuning" target="_blank" rel="noreferrer">IBM 的 RAG 与微调说明</a>（2024-08-14 发布，2026-10-15 核验）。表中的练习和排查顺序是本指南的教学设计，不是该来源对学习效果的保证。</p><p>不写代码的读者也可以完成这些练习：材料用文件夹管理，过程用表格记录，检查由自己或真实读者完成。准备进入开发时，再学习接口、结构化输出、工具调用和测试；每增加一个概念，就让它解决一个已经遇到的问题。</p><h2 id="一页任务简报" tabindex="-1">一页任务简报 <a class="header-anchor" href="#一页任务简报" aria-label="Permalink to &quot;一页任务简报&quot;">​</a></h2><p>先复制完整的<a href="./../../templates/ai-task-brief">AI 任务简报</a>到自己的私有项目目录。下面是最小字段；敏感资料先脱敏，不把密码、证件、客户记录或第三方隐私直接交给通用模型。</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># AI Task Brief</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">真实场景：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">使用者/受众：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">要完成的决策或动作：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">截止时间：</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">已知事实与来源：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">允许使用的文件：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">数据敏感等级：公开 / 内部 / 机密 / 受限</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">明确不提供的材料：</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">最终交付物：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">格式与长度：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">验收标准：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">必须由人确认的事项：</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AI 可以做：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AI 不可以做：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">人工审阅者：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">失败时如何回滚或停止：</span></span></code></pre></div><p>“体验好”“架构先进”“学会 AI”都不是验收标准。把它写成可观察的动作，例如“用户能在 10 分钟内完成一次导入，并看到一份可以解释的错误报告”。</p><h2 id="一次会话的最小协议" tabindex="-1">一次会话的最小协议 <a class="header-anchor" href="#一次会话的最小协议" aria-label="Permalink to &quot;一次会话的最小协议&quot;">​</a></h2><p>开始前，让 AI 只做边界复述：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请用不超过 8 条要点复述目标、受众、输入、验收标准、限制、未知项和你无法确认的内容。</span></span>
<span class="line"><span>列出准备使用的来源。没有来源的事实标记为待核验。</span></span>
<span class="line"><span>先不要生成最终交付，先指出最可能导致返工的 3 个风险。</span></span></code></pre></div><p>进行中，每次只推进一个可检查的切片：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把任务拆成最小可验证切片。每次只推进一个切片，并说明输入、假设、改动、检查方式和下一步。</span></span>
<span class="line"><span>如果前提冲突，暂停并提问，不要悄悄替换需求。保留失败方案和原因。</span></span></code></pre></div><p>结束时生成状态更新，而不是一篇漂亮总结：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>根据本次实际完成内容输出：</span></span>
<span class="line"><span>1. 已完成与证据位置；</span></span>
<span class="line"><span>2. 已被来源、测试或人工确认的判断；</span></span>
<span class="line"><span>3. 仍会重复的错误、风险和未决问题；</span></span>
<span class="line"><span>4. 下一项最小任务、完成标准和需要的材料。</span></span>
<span class="line"><span>不要声称记得其他会话，也不要把推断写成事实。</span></span></code></pre></div><h2 id="不同输出需要不同证据" tabindex="-1">不同输出需要不同证据 <a class="header-anchor" href="#不同输出需要不同证据" aria-label="Permalink to &quot;不同输出需要不同证据&quot;">​</a></h2><table tabindex="0"><thead><tr><th>输出</th><th>最低证据</th><th>更强证据</th></tr></thead><tbody><tr><td>解释</td><td>原始来源、关键术语、不确定项</td><td>闭卷复述、反例、迁移题</td></tr><tr><td>代码</td><td>运行结果、基本测试</td><td>边界测试、静态检查、安全审查、真实样例</td></tr><tr><td>研究</td><td>重要事实的原始链接</td><td>多源核验、数据口径、发布日期、反例</td></tr><tr><td>文稿</td><td>受众、目的、事实、结构</td><td>真实读者反馈、修订记录、版本比较</td></tr><tr><td>决策</td><td>选项、假设、成本、风险</td><td>小规模试验、决策日志、事后复盘</td></tr><tr><td>教学</td><td>学习目标、练习结果</td><td>独立迁移、延迟复测、错误变化</td></tr></tbody></table><p>对高风险内容，写“尚未确认”比把流畅猜测写成事实更专业。</p><h2 id="三次对照-证明-ai-帮了什么" tabindex="-1">三次对照：证明 AI 帮了什么 <a class="header-anchor" href="#三次对照-证明-ai-帮了什么" aria-label="Permalink to &quot;三次对照：证明 AI 帮了什么&quot;">​</a></h2><p>用<a href="./../../templates/ai-learning-log">AI 学习记录</a>为同一个任务至少留下三份样本：</p><ol><li><strong>无 AI 基线</strong>：先独立完成，记录用时、质量、卡点和信心；</li><li><strong>AI 辅助版</strong>：只让 AI 做约定的工作，记录提示、来源、采纳与拒绝的建议，以及返工；</li><li><strong>延迟独立版</strong>：间隔 3–7 天，关闭聊天和答案，换一个相近条件重新完成。</li></ol><table tabindex="0"><thead><tr><th>对照结果</th><th>更谨慎的解释</th></tr></thead><tbody><tr><td>辅助版与独立版都变好</td><td>AI 可能提供了有效脚手架，能力有机会留下</td></tr><tr><td>辅助版变好，独立版退步</td><td>成品改善了，但关键步骤可能被外包</td></tr><tr><td>时间变短，返工和错误变多</td><td>获得了速度，却积累了“速度债”</td></tr><tr><td>信心变高，事实准确度不变或下降</td><td>需要先校准信心，再增加工具权限</td></tr></tbody></table><p>至少记录任务完成、质量、独立表现、返工、成本和迁移五项。一次对照不能证明因果，但比“感觉 AI 很有用”更接近可复查的判断。</p><h2 id="常见失控与交接" tabindex="-1">常见失控与交接 <a class="header-anchor" href="#常见失控与交接" aria-label="Permalink to &quot;常见失控与交接&quot;">​</a></h2><table tabindex="0"><thead><tr><th>失控点</th><th>现场信号</th><th>立即动作</th></tr></thead><tbody><tr><td>编造事实</td><td>找不到原文、版本或数据位置</td><td>暂停传播，回到一手来源并标记未核验</td></tr><tr><td>需求漂移</td><td>回答越来越完整，却不再回答原任务</td><td>重新粘贴任务简报，要求列出冲突和未知项</td></tr><tr><td>隐私泄露</td><td>输入包含客户、身份、医疗或密钥信息</td><td>停止上传，脱敏或改用获批准的环境</td></tr><tr><td>假完成</td><td>代码能运行但没有边界测试，文章能读但没有引用</td><td>按验收标准做最小测试，不接受流畅作为完成</td></tr><tr><td>会话依赖</td><td>离开聊天就无法解释下一步</td><td>把结果写入<a href="./../../templates/ai-learning-log">AI 学习记录</a>和<a href="./../../templates/learning-state">学习状态</a></td></tr></tbody></table><p>交接时至少保存：当前目标、已完成与证据位置、仍未确认的事实、错误与风险、成本、下一项最小任务和停止/回滚条件。聊天窗口只是临时工作区，不是项目的唯一档案。</p><h2 id="从学习到项目交付" tabindex="-1">从学习到项目交付 <a class="header-anchor" href="#从学习到项目交付" aria-label="Permalink to &quot;从学习到项目交付&quot;">​</a></h2><p>当任务进入代码或团队项目，增加三道门：</p><ul><li><strong>能解释</strong>：没有聊天记录，负责人能说明关键决定和限制；</li><li><strong>能测试</strong>：真实输入、边界情况、权限和失败路径都有检查；</li><li><strong>能回滚</strong>：出现数据风险、供应商中断或质量下降时，知道谁暂停、如何通知、怎样恢复。</li></ul><p>项目目录可以使用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>00-brief/       任务简报和验收标准</span></span>
<span class="line"><span>01-baseline/    无 AI 样本和初始测试</span></span>
<span class="line"><span>02-sources/     原始资料、许可和来源索引</span></span>
<span class="line"><span>03-working/     草稿、实验和提示词</span></span>
<span class="line"><span>04-output/      可交付版本、录音或构建产物</span></span>
<span class="line"><span>05-feedback/    用户反馈和错误分类</span></span>
<span class="line"><span>06-decisions/   决策日志和未决问题</span></span>
<span class="line"><span>07-operations/  权限、监控、部署和回滚</span></span>
<span class="line"><span>learning-state.md</span></span></code></pre></div><h2 id="数据、隐私与版权" tabindex="-1">数据、隐私与版权 <a class="header-anchor" href="#数据、隐私与版权" aria-label="Permalink to &quot;数据、隐私与版权&quot;">​</a></h2><table tabindex="0"><thead><tr><th>等级</th><th>示例</th><th>默认处理</th></tr></thead><tbody><tr><td>公开</td><td>已发布文档、公开代码、公开数据</td><td>核对来源和许可证后使用</td></tr><tr><td>内部</td><td>未发布计划、流程、非敏感日志</td><td>只用组织批准的工具，限制成员和留存周期</td></tr><tr><td>机密</td><td>客户资料、合同、商业策略、未公开漏洞</td><td>未获明确批准不上传，优先本地处理或脱敏</td></tr><tr><td>受限</td><td>密钥、身份/医疗资料、儿童数据、第三方隐私</td><td>不进入通用模型，遵守组织政策和适用法律</td></tr></tbody></table><p>删除文件不等于删除历史、共享链接、导出、缓存和备份。公开文章也可能包含个人信息；先确认授权、最少必要范围和删除期限。</p><h2 id="_7-天、30-天、12-周" tabindex="-1">7 天、30 天、12 周 <a class="header-anchor" href="#_7-天、30-天、12-周" aria-label="Permalink to &quot;7 天、30 天、12 周&quot;">​</a></h2><h3 id="_7-天-完成一个可复现微交付" tabindex="-1">7 天：完成一个可复现微交付 <a class="header-anchor" href="#_7-天-完成一个可复现微交付" aria-label="Permalink to &quot;7 天：完成一个可复现微交付&quot;">​</a></h3><ul><li>写任务简报和验收标准；</li><li>保存无 AI 基线；</li><li>用七步闭环完成一个 1–3 小时交付物；</li><li>保存来源、提示、测试、反馈和状态更新；</li><li>写下 AI 帮了什么、误导了什么、撤掉后还能做什么。</li></ul><h3 id="_30-天-建立一套重复工作流" tabindex="-1">30 天：建立一套重复工作流 <a class="header-anchor" href="#_30-天-建立一套重复工作流" aria-label="Permalink to &quot;30 天：建立一套重复工作流&quot;">​</a></h3><ul><li>对同类任务完成四次闭环；</li><li>比较时间、质量、返工、成本和独立表现；</li><li>删除不能改善结果的步骤；</li><li>做一次失败复盘，而不只展示成功案例。</li></ul><h3 id="_12-周-交付给真实用户或组织" tabindex="-1">12 周：交付给真实用户或组织 <a class="header-anchor" href="#_12-周-交付给真实用户或组织" aria-label="Permalink to &quot;12 周：交付给真实用户或组织&quot;">​</a></h3><ul><li>每 2–4 周邀请真实受众反馈；</li><li>完成事实、测试、安全、隐私、版权、成本和交接检查；</li><li>导出材料与状态，写一页复盘和下一周期决策；</li><li>证据不足时缩小问题、改变对象或停止，不用更多提示词掩盖缺口。</li></ul><p>把三次对照和周期结果放入<a href="./../../templates/90-day-cycle">九十日行动总表</a>，下一周期只改变一个变量。</p><h2 id="来源与边界" tabindex="-1">来源与边界 <a class="header-anchor" href="#来源与边界" aria-label="Permalink to &quot;来源与边界&quot;">​</a></h2><ul><li><strong>个人经历</strong>：主要来自 <a href="./../part-2/my-story">我的故事</a>、<a href="./../part-2/entrepreneurship">创业篇</a> 和 <a href="./../../projects">作者项目与现实实践</a>，属于作者个人记录，不是普遍规律。</li><li><strong>产品信息</strong>：使用 <a href="./../part-1/7-ai">用 AI 学英语</a> 中列出的官方帮助页；功能、地区和套餐会变化。</li><li><strong>项目现状</strong>：中国词元云、<code>token.love</code>、公开文章和实体产业计划均有利益关系或待验证范围，不能当作独立测评或收入证明。</li><li><strong>上次核验日期</strong>：2026-10-15。产品功能和项目现状仍需在实际使用前重新检查；本次新增的 AI 概念来源见正文和归属登记。</li></ul><h2 id="结语-把能力留在人身上" tabindex="-1">结语：把能力留在人身上 <a class="header-anchor" href="#结语-把能力留在人身上" aria-label="Permalink to &quot;结语：把能力留在人身上&quot;">​</a></h2><p>AI 最容易制造的，不只是错误答案，还有一种过早的完成感。解释很流畅，代码能够运行，计划已经排好，我们便以为问题被真正理解了。可答案出现的速度，常常快过判断形成的速度。</p><p>一次学习如果值得继续，结束时应该留下聊天记录带不走的东西：一个更准确的问题，一条能够追溯的来源，一次失败的测试，一个被证据改变的判断，一件别人能够使用的作品，以及在工具关闭以后仍然知道怎样往下做的人。</p><p>学习不是让 AI 替你抵达，而是借它走到原本看不见的地方，再亲自确认脚下是什么。关闭窗口，向一个真实的人解释，完成下一步，并承担结果。能力若能跟着你离开对话，它才真正留了下来。</p>`,86)])])}const b=t(e,[["render",l]]);export{g as __pageData,b as default};
